/* PG18 facts recorded by meson on little-endian ppc64; meson's machine name does not
   distinguish the byte orders. */
#define ALIGNOF_DOUBLE 8
#define ALIGNOF_INT 4
#define ALIGNOF_INT64_T 8
#define ALIGNOF_LONG 8
#define ALIGNOF_PG_INT128_TYPE 16
#define ALIGNOF_SHORT 2
#define MAXIMUM_ALIGNOF 8
#define PG_INT128_TYPE __int128
#define PG_MAJORVERSION_NUM 18
#define PG_VERSION_NUM 180006
#define PG_VERSION_STR "PostgreSQL 18.6 on ppc64-linux, compiled by gcc-14.2.0, 64-bit"
#define SIZEOF_LONG 8
#define SIZEOF_LONG_LONG 8
#define SIZEOF_SIZE_T 8
#define SIZEOF_VOID_P 8
